import{_ as t}from"./chunks/qr_ob1_debug.BFcqNe1b.js";import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r,o as s,c as i,a3 as o}from"./chunks/framework.g9mfNVRQ.js";const f=JSON.parse('{"title":"G7, ONE+","description":"","frontmatter":{"source_hash":"5d92e9e918","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/troubleshoot/g7.md","filePath":"fr/troubleshoot/g7.md"}'),n={name:"fr/troubleshoot/g7.md"};function l(u,e,p,c,d,m){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="g7-one-troubleshooting" tabindex="-1">Dépannage G7, ONE+ <a class="header-anchor" href="#g7-one-troubleshooting" aria-label="Permalink to &quot;Dépannage G7, ONE+ {#g7-one-troubleshooting}&quot;">​</a></h1><p>Si ce n&#39;est pas déjà fait, consultez d&#39;abord <a href="./../install/g7.html">comment configurer le G7/ONE+</a>. Beaucoup des causes décrites ci-dessous sont les mêmes que pour le <a href="./g6.html">G6/ONE</a> : la force du signal et la batterie y sont traitées, et nous y renvoyons plutôt que de les répéter.</p><h2 id="step-by-step-troubleshooting" tabindex="-1">Dépannage pas à pas <a class="header-anchor" href="#step-by-step-troubleshooting" aria-label="Permalink to &quot;Dépannage pas à pas {#step-by-step-troubleshooting}&quot;">​</a></h2><p>Si xDrip est réglé pour collecter directement depuis un G7/ONE+ mais ne reçoit pas de données, suivez ces étapes dans l&#39;ordre :</p><ol><li>Désactivez le <a href="./../use/misc.html#engineering-mode">Mode développeur</a>.</li><li>Désinstallez l&#39;application Dexcom, ou toute autre application qui se connecte directement au capteur.</li><li>Vérifiez le capteur lui-même : voyez-vous le filament dépasser sur le dessus ? Si oui, prenez-le en photo pour Dexcom : même une fois connecté, le capteur ne donnera pas de valeurs exploitables puisque le filament n&#39;a jamais vraiment été inséré sous votre peau, et il vous en faudra un nouveau.</li><li><strong>« Missing QR Code » sur la page Dex Status</strong> : utilisez Paramètres → Configuration automatique pour scanner le QR code du <a href="./../install/g7.html#setup-xdrip">guide de configuration</a>, et non un code imprimé sur le capteur lui-même, puis appuyez sur <strong>Redémarrer le collecteur</strong> dans la page d&#39;état classique.</li><li><strong>« Mismatch - wait » sur la page Dex Status</strong> : vous avez probablement mal saisi le code d&#39;appairage, ou des capteurs déjà utilisés se trouvent à proximité. Éloignez les capteurs déjà utilisés de plus de 10 mètres, vérifiez le code d&#39;appairage par rapport à celui imprimé sur l&#39;applicateur, puis appuyez sur <strong>Redémarrer le collecteur</strong>.</li><li><strong>Vérifiez la connectivité</strong> : s&#39;il n&#39;y en a aucune, utilisez un <a href="./g6.html#how-strong-is-the-transmitter-signal">scanner Bluetooth</a> pour vérifier si l&#39;émetteur est seulement visible, après avoir éloigné les anciens appareils. S&#39;il n&#39;est toujours pas visible, approchez l&#39;aimant de l&#39;applicateur du capteur pendant quelques secondes (cela peut déclencher son activation), puis vérifiez à nouveau avec le scanner et appuyez sur <strong>Redémarrer le collecteur</strong>.</li><li><strong>« Deep Sleeping Errors », « Checking Auth Errors », « Scanning Errors » ou « Initializing Errors » sur la page Dex Status</strong> : <ol><li>Notez l&#39;ID de l&#39;émetteur actuel à 4 chiffres depuis Paramètres.</li><li>Remplacez son dernier chiffre par un autre.</li><li>Désactivez la collecte dans xDrip, et désactivez temporairement toute pompe, tout récepteur ou toute montre connectés directement au capteur.</li><li>Attendez 15 minutes que le G7 passe en <a href="#g7-rapid-reconnect-mode">mode de reconnexion rapide</a>.</li><li>Supprimez les appareils Bluetooth nommés <code>DXCM*</code>, <code>DX01*</code>, <code>DX02*</code> ou <code>DX04*</code> de la liste des appareils connectés / précédemment connectés d&#39;Android.</li><li>Réactivez le collecteur Dex de xDrip (sélectionnez Dex comme source de données matérielle) et remettez l&#39;ID de l&#39;émetteur correct que vous aviez noté.</li><li>Allez sur la page Dex Status, attendez jusqu&#39;à une minute une demande d&#39;appairage et acceptez-la ; si aucune n&#39;apparaît, redémarrez le téléphone.</li><li>Une fois connecté avec 3 valeurs consécutives, vous pouvez réactiver votre pompe, votre récepteur ou votre montre.</li></ol></li><li><strong>« Sensor Failed 7 » sur la page Dex Status</strong> : évitez de vous allonger sur le capteur et détendez le membre qui le porte, hydratez-vous bien et attendez jusqu&#39;à 3 heures que les valeurs reviennent. Si les valeurs reviennent mais continuent de disparaître au hasard, consultez <a href="./g6.html#intermittent-connectivity">Connectivité intermittente</a>.</li></ol><h2 id="g7-rapid-reconnect-mode" tabindex="-1">Mode de reconnexion rapide du G7 <a class="header-anchor" href="#g7-rapid-reconnect-mode" aria-label="Permalink to &quot;Mode de reconnexion rapide du G7 {#g7-rapid-reconnect-mode}&quot;">​</a></h2><p>En temps normal, un G7/ONE+ émet une fois toutes les 5 minutes, avec à chaque fois un échange d&#39;accusés de réception dans les deux sens. S&#39;il manque trois accusés de réception d&#39;affilée (15 minutes sans échange réussi), il passe en mode de reconnexion rapide : il répète chaque valeur jusqu&#39;à 4 fois de plus, une fois par minute, pour qu&#39;une application qui se reconnecte n&#39;ait pas à attendre un cycle complet de 5 minutes pour l&#39;attraper. Cela dure jusqu&#39;à 12 heures, ou jusqu&#39;à ce que l&#39;application se reconnecte, selon ce qui arrive en premier.</p><p>Dès qu&#39;un échange réussit, les émissions supplémentaires s&#39;arrêtent. xDrip lit l&#39;horodatage de la valeur qu&#39;il reçoit (qui correspond toujours au cycle sous-jacent de 5 minutes) : il se resynchronise donc correctement sur le rythme normal, même s&#39;il a capté l&#39;une des émissions supplémentaires de chaque minute plutôt que la « vraie ».</p><h2 id="ob1-debugging-logs" tabindex="-1">Journaux de débogage OB1 <a class="header-anchor" href="#ob1-debugging-logs" aria-label="Permalink to &quot;Journaux de débogage OB1 {#ob1-debugging-logs}&quot;">​</a></h2><p>Ceci s&#39;applique aussi bien au G6, ONE, G7 qu&#39;au ONE+ : ils utilisent tous le même collecteur OB1, qui n&#39;enregistre que très peu de détails par défaut. Si un développeur vous demande des journaux détaillés pour dépanner un problème de connexion, activez d&#39;abord la journalisation OB1 complète.</p><p>Le plus simple est de scanner ce QR code avec Paramètres, <a href="./../use/copysettings.html#auto-configure">Configuration automatique</a> et d&#39;accepter l&#39;importation. Il ne modifie qu&#39;un seul paramètre, Balises supplémentaires pour le log.</p><p>QR code - Cliquez sur l&#39;image pour l&#39;agrandir</p><p><a href="../../troubleshoot/images/qr_ob1_debug.png"><img src="'+t+'" style="zoom:50%;"></a></p><p>Vous pouvez aussi saisir les balises à la main :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a><br>   <a href="./../use/lesscommon.html#extra-logging-settings">Paramètres de logs supplémentaires</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Balises supplémentaires pour le log</p><p> Ob1G5CollectionService:v,Ob1G5StateMachine:v</p></div><p>Ensuite :</p><ul><li>Attendez que le problème se produise réellement avant d&#39;envoyer les journaux. Activer la journalisation seule ne capture encore rien d&#39;utile.</li><li>Ouvrez le <a href="./../use/3dotsmenu.html#events-log">Journal des événements</a> depuis le menu à 3 points, appuyez sur Télécharger les Logs et ajoutez une note identifiant l&#39;appareil afin de pouvoir faire le lien lorsque vous signalez le problème.</li><li>Désactivez-la ensuite : videz le champ Balises supplémentaires pour le log et validez. Sinon, elle continue à générer un gros volume de journaux supplémentaires.</li></ul><h2 id="shared-with-g6one" tabindex="-1">Commun avec le G6/ONE <a class="header-anchor" href="#shared-with-g6one" aria-label="Permalink to &quot;Commun avec le G6/ONE {#shared-with-g6one}&quot;">​</a></h2><p>Ces points s&#39;appliquent aussi aux émetteurs G7/ONE+ ; consultez la page <a href="./g6.html">Dépannage G6, ONE</a> pour tous les détails :</p><ul><li><a href="./g6.html#how-strong-is-the-transmitter-signal">Quelle est la force du signal de l&#39;émetteur ?</a></li><li><a href="./g6.html#how-good-is-the-battery">Quel est l&#39;état de la batterie ?</a></li><li><a href="./g6.html#transmitter-queue-stuck">File d&#39;attente de l&#39;émetteur bloquée</a></li></ul>',21)])])}const b=r(n,[["render",l]]);export{f as __pageData,b as default};
